entries[163988] = { ["name"] = "Arkaner Zorn: Verschiebung", ["text"] = "Wirken in 1.5 sek.\nKaiser Mar'gok trifft einen zufälligen Spielercharakter mit arkaner Energie, die ihn 4 Sek. lang brandmarkt.\n\nWenn das Brandmal ausläuft, fügt es dem Träger 3591 Arkanschaden zu und springt zum nächsten Verbündeten innerhalb von 200 Metern.\n\nJedes Mal, wenn 'Arkaner Zorn' springt, nimmt der Schaden um 25% zu und die Reichweite um 50% ab.\n\nVerschiebung: Gebrandmarkte Spielercharaktere können sich nicht mehr als 10 Meter vom Ort entfernen, an dem 'Gebrandmarkt' angewendet wurde." }
entries[163989] = { ["name"] = "Arkaner Zorn: Stärkung", ["text"] = "Wirken in 1.5 sek.\nKaiser Mar'gok trifft einen zufälligen Spielercharakter mit arkaner Energie, die ihn 4 Sek. lang brandmarkt.\n\nWenn das Brandmal ausläuft, fügt es dem Träger 3591 Arkanschaden zu und springt zum nächsten Verbündeten innerhalb von 200 Metern.\n\nJedes Mal, wenn 'Arkaner Zorn' springt, nimmt der Schaden um 25% zu und die Reichweite um 25% ab.\n\nStärkung: Die Sprungreichweite von 'Arkaner Zorn' verringert sich mit jedem Sprung nur um 25%." }
entries[163990] = { ["name"] = "Arkaner Zorn: Reproduktion", ["text"] = "Wirken in 1.5 sek.\nKaiser Mar'gok trifft einen zufälligen Spielercharakter mit arkaner Energie, die ihn 4 Sek. lang brandmarkt.\n\nWenn das Brandmal ausläuft, fügt es dem Träger 3591 Arkanschaden zu und springt zum nächsten Verbündeten innerhalb von 200 Metern über.\n\nJedes Mal, wenn 'Arkaner Zorn' überspringt, nimmt der Schaden um 25% zu und die Reichweite um 50% ab.\n\nReproduktion: 'Arkaner Zorn' springt beim ersten Sprung auf zwei zufällige Ziele über und brandmarkt beide." }
