entries[164061] = { ["name"] = "Tod von oben", ["text"] = "Unbegrenzte Reichweite\nWirken in 5 sek.\nSchmettert auf den Boden, fügt Gegnern in der Nähe 9927 körperlichen Schaden zu und stößt sie zurück. Betäubt den Zaubernden und erhöht den von ihm erlittenen Schaden 5 Sek. lang um 200%." }
