entries[164063] = { ["name"] = "Seuchenstoß", ["text"] = "Nahkampfreichweite\nSofort\nEin heftiger Schlag, der Waffenschaden verursacht, das Ziel verseucht und im Verlauf von 12 Sek. 37 Schattenschaden hervorruft." }
