entries[164065] = { ["name"] = "Antimagisches Feld", ["text"] = "1 Rune / -10 Runenmacht\nSofort\nPlatziert ein großes, ortsgebundenes antimagisches Feld, das den erlittenen Zauberschaden aller darin befindlichen Gruppen- oder Schlachtzugsmitglieder um 49% verringert. Das antimagische Feld hält 6 Sek. lang an oder bis es (0 + 2 * Angriffskraft) Zauberschaden absorbiert hat." }
entries[164066] = { ["name"] = "Totenerweckung", ["text"] = "30 Meter Reichweite\nSofort\nErweckt einen Ghul, der an Eurer Seite kämpft. Steht kein humanoider Leichnam zur Verfügung, der Erfahrung oder Ehre gewährt, wird Leichenstaub benötigt, um den Zauber zu wirken. Ihr könnt nur maximal einen Ghul gleichzeitig beschwören. Hält 1 Min. lang." }
entries[164067] = { ["name"] = "Frostnova", ["text"] = "75 Mana\nSofort\nFügt Gegnern in der Nähe Frostschaden zu und macht sie bis zu 8 Sek. lang bewegungsunfähig." }
entries[164068] = { ["name"] = "Frostrüstung", ["text"] = "Sofort 10 sek. Abklingzeit\nUmgibt den Zaubernden mit einer Frostschicht, die 30 Min. lang bestehen bleibt. Das dicke Eis erhöht die Rüstung, verringert die Bewegungsgeschwindigkeit von Nahkampfangreifern und erhöht die Zeit zwischen ihren Angriffen." }
