entries[164072] = { ["name"] = "Elektroschmettern", ["text"] = "2 Meter Reichweite\nSofort\nKracht mit vollem Gewicht auf den Boden, was allen Gegnern im Umkreis von 10 Metern um den Einschlagspunkt Naturschaden zufügt." }
entries[164073] = { ["name"] = "Elektroschmettern", ["text"] = "8 - 40 Meter Reichweite\nSofort\nHüpft in die Luft und kracht mit voller Wucht herunter, was allen Gegnern im Umkreis von 2 Metern um den Einschlagspunkt körperlichen Schaden zufügt und sie zurückstößt." }
entries[164074] = { ["name"] = "Destruktive Resonanz", ["text"] = "Sofort" }
entries[164075] = { ["name"] = "Destruktive Resonanz: Verschiebung", ["text"] = "Wirken in 1.5 sek.\nKaiser Mar'gok beschwört eine arkane Mine unter einem zufälligen Gegner, die sich nach 3 Sek. scharf macht. Die Mine bleibt 1 Min. bestehen und wird von jedem Spielercharakter ausgelöst, der ihren Radius nach dem Scharfmachen betritt.\n\nBei Auslösung explodiert 'Destruktive Resonanz', fügt allen Spielercharakteren in ihrem Radius 9019 Arkanschaden zu und erhöht deren erlittenen Arkanschaden 1 Min. lang um 45%.\n\nVerlagerung: 'Destruktive Resonanz' wächst innerhalb von 30 Sek. auf das Doppelte ihrer ursprünglichen Größe an." }
entries[164076] = { ["name"] = "Destruktive Resonanz: Stärkung", ["text"] = "Wirken in 1.5 sek.\nKaiser Mar'gok beschwört eine arkane Mine unter einem zufälligen Gegner, die nach 3 Sek. scharf ist. Die scharfe Mine bleibt 2 Min. bestehen und wird von jedem Spielercharakter ausgelöst, der ihren Radius nach dem Scharfmachen betritt.\n\nWird die Mine ausgelöst, explodiert 'Destruktive Resonanz', fügt allen Spielercharakteren in ihrem Radius 9019 Arkanschaden zu und erhöht deren erlittenen Arkanschaden 1 Min. lang um 45%.\n\nStärkung: 'Destruktive Resonanz' hält 2 Min. lang an." }
entries[164077] = { ["name"] = "Destruktive Resonanz: Reproduktion", ["text"] = "Wirken in 1.5 sek.\nKaiser Mar'gok beschwört eine arkane Mine unter einem zufälligen Gegner, die nach 3 Sek. scharf ist. Die scharfe Mine bleibt 1 Min. bestehen und wird von jedem Spielercharakter ausgelöst, der ihren Radius nach dem Scharfmachen betritt.\n\nWird die Mine ausgelöst, explodiert 'Destruktive Resonanz', fügt allen Spielercharakteren in ihrem Radius 9019 Arkanschaden zu und erhöht deren erlittenen Arkanschaden 1 Min. lang um 45%.\n\nReproduktion: Wenn 'Destruktive Resonanz' explodiert oder ausläuft, werden zwei weitere 'destruktive Resonanzen in der Nähe platziert." }
